/**
 * Type stub for the `$droplets/env` module, available to droplet authors.
 * The real module is generated by the Vite plugin.
 */
/** `true` in the browser, `false` on the server. */
export const browser: boolean = false;
/** `true` under `vite dev`. */
export const dev: boolean = false;
/** `true` while `vite build` prerenders droplets. */
export const building: boolean = false;
